import builtins, time
def frames(n):
    for _ in range(n):
        app.update(True)
def run_for(seconds):
    t = time.monotonic()
    while time.monotonic() - t < seconds:
        app.update(True)
def targets():
    return {j['name']: j['target'] for j in app.actions.run('robot.joints')['joints']}
def until(done):
    deadline = time.monotonic() + 20.0
    while not done(targets()):
        assert time.monotonic() < deadline, targets()
        app.update(True)
    return targets()
builtins.tp_frames, builtins.tp_run_for, builtins.tp_targets, builtins.tp_until = frames, run_for, targets, until

from nuka.editor.app import ActionError
root = app.actions.run('robot.links')['links'][0]['path']
try:
    app.actions.run('teleop.use', link=root)
except ActionError as e:
    assert 'below a root' in str(e), e
else:
    raise AssertionError('teleop took a root link')

